// Cheap in-memory column verdict first (AC10), then the scoped row write.
const verdict = this.deps.engine.allowUpdate(
  ac.permissions, "organization", patch, ac.bag,
);
if (!verdict.allow) {
  throw this.deps.errors.forbidden(verdict.reason ?? "cannot update organization");
}

const scope = this.deps.engine.resolveUpdate(
  ac.permissions, "organization", ac.bag,
);
const updated = await this.deps.orgRepo.update(
  visibility, orgId, patch, scope, ac.gateDb,
);

// null ⇒ the Scope admitted no such row (denied, AC6/AC9)
if (!updated) throw this.deps.errors.forbidden("cannot update organization");

{
  name: "manage_own_notes",
  entity: "note",
  actions: ["read", "update", "delete"],
  rules: [
    {
      context: [{ bag: "$session.organization.type", has: { value: "company" } }],
      target:  [{ field: "note.authorUserId", has: { bag: "$session.user.id" } }],
    },
  ],
}

{
  name: "append_song_session",
  entity: "song_session_slice",
  actions: ["create"],
  rules: [
    // the song's creator
    { context: [], target: [],
      payload: [{ bag: "$requestBody.songId", join: "song",
                  where: [{ field: "song.creatorUserId", has: { bag: "$session.user.id" } }] }] },

    // …or someone it is edit-shared with. song_share is keyed by songId,
    // not by id, so the far-side column is named.
    { context: [], target: [],
      payload: [{ bag: "$requestBody.songId", join: "song_share", on: "songId",
                  where: [{ field: "song_share.userId", has: { bag: "$session.user.id" } }] }] },
  ],
}

